   "solution": {
    "ppu.c": "#include <string.h>\n#include \"ppu.h\"\n#include \"cart.h\"\n\n// ---------- Memory ----------\n\nstatic uint8_t vram[0x800];      // 2 KB: two physical nametables\nstatic uint8_t palette_ram[32];\n\n// ---------- Registers ----------\n\nstatic uint8_t ctrl;             // 2000 PPUCTRL\nstatic uint8_t status;           // 2002 PPUSTATUS\nstatic uint16_t vram_addr;       // 2006 PPUADDR: where 2007 reads and writes\nstatic int write_latch;          // 0: next 2005/2006 write is the first one\nstatic uint8_t read_buffer;      // 2007 reads are delayed by one\n\nvoid ppu_reset(void) {\n    memset(vram, 0, sizeof vram);\n    memset(palette_ram, 0, sizeof palette_ram);\n    ctrl = 0;\n    status = 0;\n    vram_addr = 0;\n    write_latch = 0;\n    read_buffer = 0;\n}\n\n// Which byte of vram a nametable address 2000-3EFF uses.\nstatic uint16_t nametable_index(uint16_t addr) {\n    uint16_t offset = (addr - 0x2000) & 0x0FFF;   // 0000-0FFF: four 1 KB tables\n    int table = offset / 0x400;                   // 0, 1, 2 or 3\n    int physical;\n    if (cart_mirroring() == MIRROR_VERTICAL) {\n        physical = table & 1;                     // 0 1 / 0 1\n    } else {\n        physical = table >> 1;                    // 0 0 / 1 1\n    }\n    return (uint16_t)(physical * 0x400 + (offset & 0x3FF));\n}\n\n// Which byte of palette_ram an address 3F00-3FFF uses.\nstatic int palette_index(uint16_t addr) {\n    int i = addr & 0x1F;\n    // 3F10, 3F14, 3F18 and 3F1C are the same bytes as 3F00, 3F04, 3F08, 3F0C.\n    if ((i & 0x13) == 0x10) {\n        i &= 0x0F;\n    }\n    return i;\n}\n\nuint8_t ppu_read(uint16_t addr) {\n    addr &= 0x3FFF;\n    if (addr < 0x2000) {\n        return cart_ppu_read(addr);\n    }\n    if (addr < 0x3F00) {\n        return vram[nametable_index(addr)];\n    }\n    return palette_ram[palette_index(addr)];\n}\n\nvoid ppu_write(uint16_t addr, uint8_t value) {\n    addr &= 0x3FFF;\n    if (addr < 0x2000) {\n        cart_ppu_write(addr, value);\n    } else if (addr < 0x3F00) {\n        vram[nametable_index(addr)] = value;\n    } else {\n        palette_ram[palette_index(addr)] = value;\n    }\n}\n\n// ---------- Tiles ----------\n\n// A tile is 16 bytes: 8 bytes for bit 0 of each pixel (one byte per row),\n// then 8 bytes for bit 1. In each byte, bit 7 is the leftmost pixel.\nvoid ppu_tile_row(uint16_t table, uint8_t tile, int row, uint8_t out[8]) {\n    uint16_t base = (uint16_t)(table + tile * 16 + row);\n    uint8_t lo = ppu_read(base);\n    uint8_t hi = ppu_read((uint16_t)(base + 8));\n    for (int x = 0; x < 8; x++) {\n        int bit = 7 - x;\n        out[x] = (uint8_t)(((lo >> bit) & 1) | (((hi >> bit) & 1) << 1));\n    }\n}\n\n// ---------- The CPU's view: 2000-2007 ----------\n\nuint8_t ppu_register_read(int reg) {\n    switch (reg) {\n    case 2: {                                       // PPUSTATUS\n        uint8_t value = (uint8_t)((status & 0xE0) | (read_buffer & 0x1F));\n        write_latch = 0;                            // and resets the 2005/2006 latch\n        return value;\n    }\n    case 7: {                                       // PPUDATA\n        uint16_t addr = vram_addr & 0x3FFF;\n        uint8_t value;\n        if (addr >= 0x3F00) {\n            value = ppu_read(addr);                 // the palette answers at once\n            read_buffer = ppu_read((uint16_t)(addr - 0x1000));\n        } else {\n            value = read_buffer;                    // everything else is one read late\n            read_buffer = ppu_read(addr);\n        }\n        vram_addr = (uint16_t)((vram_addr + ((ctrl & 0x04) ? 32 : 1)) & 0x3FFF);\n        return value;\n    }\n    }\n    return 0;\n}\n\nvoid ppu_register_write(int reg, uint8_t value) {\n    switch (reg) {\n    case 0:                                         // PPUCTRL\n        ctrl = value;\n        break;\n    case 6:                                         // PPUADDR: high byte, then low byte\n        if (write_latch == 0) {\n            vram_addr = (uint16_t)(((value & 0x3F) << 8) | (vram_addr & 0x00FF));\n        } else {\n            vram_addr = (uint16_t)((vram_addr & 0xFF00) | value);\n        }\n        write_latch ^= 1;\n        break;\n    case 7:                                         // PPUDATA\n        ppu_write(vram_addr, value);\n        vram_addr = (uint16_t)((vram_addr + ((ctrl & 0x04) ? 32 : 1)) & 0x3FFF);\n        break;\n    }\n}\n"
   },
   "harness": "#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include \"cart.h\"\n#include \"ppu.h\"\n// Builds a small iNES file in memory for the tests.\nstatic uint8_t rom_file[16 + 512 + 2 * 0x4000 + 0x2000];\n\nstatic long make_rom(int prg_banks, int chr_banks, uint8_t flags6, uint8_t flags7) {\n    memset(rom_file, 0, sizeof rom_file);\n    memcpy(rom_file, \"NES\\x1A\", 4);\n    rom_file[4] = (uint8_t)prg_banks;\n    rom_file[5] = (uint8_t)chr_banks;\n    rom_file[6] = flags6;\n    rom_file[7] = flags7;\n    long trainer = (flags6 & 0x04) ? 512 : 0;\n    uint8_t *p = rom_file + 16 + trainer;\n    for (long i = 0; i < prg_banks * 0x4000L; i++) *p++ = (uint8_t)(i * 7 + (i >> 8));\n    for (long i = 0; i < chr_banks * 0x2000L; i++) *p++ = (uint8_t)(0xA0 ^ i ^ (i >> 4));\n    return 16 + trainer + prg_banks * 0x4000L + chr_banks * 0x2000L;\n}\n\nstatic uint8_t *read_file(const char *name, long *size) {\n    FILE *f = fopen(name, \"rb\");\n    if (!f) return NULL;\n    fseek(f, 0, SEEK_END);\n    *size = ftell(f);\n    fseek(f, 0, SEEK_SET);\n    uint8_t *data = malloc(*size);\n    if (data && fread(data, 1, *size, f) != (size_t)*size) { free(data); data = NULL; }\n    fclose(f);\n    return data;\n}\n\nstatic void w(int reg, uint8_t v) { ppu_register_write(reg, v); }\nstatic uint8_t rd(int reg) { return ppu_register_read(reg); }\n\nint main(void) {\n    int t = 0;\n    if (scanf(\"%d\", &t) != 1) return 1;\n    cart_load(rom_file, make_rom(1, 0, 0x01, 0));\n    ppu_reset();\n    if (t == 1) {\n        w(6, 0x20); w(6, 0x05); w(7, 0x41); w(7, 0x42);\n        printf(\"2005=%02X 2006=%02X 2007=%02X\\n\", ppu_read(0x2005), ppu_read(0x2006), ppu_read(0x2007));\n    }\n    if (t == 2) {\n        ppu_write(0x2105, 0x41); ppu_write(0x2106, 0x42);\n        w(6, 0x21); w(6, 0x05);\n        uint8_t a = rd(7), b = rd(7), c = rd(7);\n        printf(\"three reads from 2105: %02X %02X %02X\\n\", a, b, c);\n    }\n    if (t == 3) {\n        w(0, 0x04);\n        w(6, 0x20); w(6, 0x00); w(7, 0x01); w(7, 0x02); w(7, 0x03);\n        printf(\"2000=%02X 2020=%02X 2040=%02X 2001=%02X\\n\", ppu_read(0x2000), ppu_read(0x2020), ppu_read(0x2040), ppu_read(0x2001));\n    }\n    if (t == 4) {\n        w(6, 0x3F); w(6, 0x00); w(7, 0x0F); w(7, 0x16);\n        ppu_write(0x2F00, 0x77);\n        w(6, 0x3F); w(6, 0x00);\n        uint8_t a = rd(7);\n        w(6, 0x20); w(6, 0x00);\n        uint8_t b = rd(7);\n        printf(\"palette read: %02X, then a nametable read gives the buffer: %02X\\n\", a, b);\n    }\n    if (t == 5) {\n        w(6, 0x21);\n        uint8_t s = rd(2);\n        w(6, 0x20); w(6, 0x00); w(7, 0x5A);\n        printf(\"PPUSTATUS read %02X; 2000=%02X 2100=%02X\\n\", s, ppu_read(0x2000), ppu_read(0x2100));\n    }\n    if (t == 6) {\n        w(6, 0x3F); w(6, 0xFF); w(7, 0x30); w(7, 0x55);\n        printf(\"3FFF=%02X 0000=%02X\\n\", ppu_read(0x3FFF), ppu_read(0x0000));\n        w(6, 0x7F); w(6, 0x00); w(7, 0x12);\n        printf(\"writing PPUADDR 7F00 reaches 3F00: %02X\\n\", ppu_read(0x3F00));\n    }\n    return 0;\n}\n",
